"""Scientific fixtures for the proposed observer; no public/native API asserted."""

from dataclasses import replace

import numpy as np
import pytest
from numpy.testing import assert_allclose, assert_array_equal

from .balloon_windkessel_reference import (
    NOMINAL_PARAMETERS,
    REST_STATE,
    bold_fraction,
    solve_held_drive,
)


# Pins generated by an independent Radau solve of [s, log(f), log(v), log(q)]
# at 20 ms neural / 10 ms hemodynamic cadence; split at every neural tick.
@pytest.fixture(params=["step", "impulse", "oscillation"])
def held_drive_pins(request):
    ms = np.arange(300) * 20
    if request.param == "step":
        return (
            0.4 * (ms >= 200),
            [220, 800, 3200, 6000],
            [(0.00787689483209, 1.000079179336, 1.000000531516, 1.000000119825),
             (0.135056837263, 1.050543197285, 1.007309803904, 0.999793324964),
             (-0.023574000473, 1.181112344360, 1.055953326292, 0.936871245923),
             (0.003396131202, 1.162984057584, 1.049212674154, 0.933073783997)],
            [-2.06260215471e-8, -6.35791898826e-5, 0.00678444266981, 0.00732377039490],
            [-1.95982488482e-6, -4.86966034575e-5, 6.21166430396e-5, 0.000759102195600],
        )
    if request.param == "impulse":
        # Finite rectangular pulse: 0.5 s⁻² for 0.04 s, area 0.02 s⁻¹, not a state jump.
        return (
            0.5 * ((ms >= 200) & (ms < 240)),
            [220, 240, 800, 3200],
            [(0.009846118540, 1.000098974170, 1.000000664395, 1.000000149779),
             (0.019384434112, 1.000391792655, 1.000005191318, 1.000001126923),
             (0.003889333082, 1.006678024787, 1.001361310703, 0.999838195108),
             (-0.000340569677, 0.998827660255, 0.999788828526, 0.999011724737)],
            [-2.57823413340e-8, -1.96293435705e-7, 2.88721444191e-6, 0.000120046833833],
            [-1.33200596079e-6, -7.56278200580e-6, 3.56908806273e-5, 0.000116471968747],
        )
    sec = ms / 1000
    return (
        0.25 * np.sin(2 * np.pi * 0.35 * sec) + 0.1 * np.sin(2 * np.pi * 1.2 * sec),
        [220, 800, 3200, 6000],
        [(0.022433108398, 1.001706811853, 1.000083580349, 1.000013633136),
         (0.062329594211, 1.031943776086, 1.005358408004, 0.999569249267),
         (0.014873647570, 0.932391578949, 0.982909826279, 0.992607131228),
         (-0.005371325368, 0.938708031227, 0.987261394456, 0.994511493114)],
        [-2.62406725703e-6, -1.33290643435e-5, 0.00108278670007, 0.000804729088376],
        [-4.54307171061e-6, -2.83689574437e-5, 8.82238243313e-5, 0.000503193797897],
    )


@pytest.fixture
def held_drive_trajectory(held_drive_pins):
    return solve_held_drive(held_drive_pins[0], neural_dt_ms=20, hemo_dt_ms=10)


def test_held_drive_trajectory_pins(held_drive_pins, held_drive_trajectory):
    _, sample_ms, expected_states, _, _ = held_drive_pins
    traj = held_drive_trajectory
    assert traj.states.dtype == np.float64
    assert np.all(np.isfinite(traj.states))
    assert np.all(traj.states[:, 1:] > 0)
    indices = np.searchsorted(traj.times_ms, sample_ms)
    assert_array_equal(traj.times_ms[indices], sample_ms)
    assert_allclose(traj.states[indices], expected_states, rtol=0, atol=2e-11)


def test_held_drive_readout_pins(held_drive_pins, held_drive_trajectory):
    _, sample_ms, _, expected_readouts, expected_windows = held_drive_pins
    traj = held_drive_trajectory
    indices = np.searchsorted(traj.times_ms, sample_ms)
    assert_allclose(bold_fraction(traj.states[indices]), expected_readouts, rtol=0, atol=2e-12)
    _, _, means = traj.windowed_bold(period_ms=400)
    assert_allclose(means[:4], expected_windows, rtol=0, atol=2e-12)


def test_equilibrium_for_zero_drive_and_fresh_solve():
    driven = solve_held_drive([0.5] * 4, neural_dt_ms=20, hemo_dt_ms=10)
    assert driven.states[-1, 0] > 0
    traj = solve_held_drive(np.zeros(40), neural_dt_ms=20, hemo_dt_ms=10)
    assert_allclose(traj.states, np.tile([0, 1, 1, 1], (81, 1)), rtol=0, atol=2e-14)
    assert_allclose(bold_fraction(traj.states), 0, rtol=0, atol=2e-14)
    assert_allclose(traj.windowed_bold(period_ms=100)[2], 0, rtol=0, atol=2e-14)


def test_bold_readout_uses_revised_nonlinear_fractional_coefficients():
    # For v=1 only the two q terms survive; for q=v the q/v term vanishes.
    # The third state exercises all three terms, with q/v != q and q/v != 1.
    states = [[0, 1, 1, 0.75], [0, 1, 1.1, 1.1], [0, 1, 1.2, 0.82]]
    assert_allclose(bold_fraction(states), [0.0297264, -0.01309056, 0.0184963413333333],
                    rtol=0, atol=1e-14)


def test_physical_duration_is_independent_of_hemodynamic_mesh():
    u = 0.4
    drive = np.full(50, u)  # 50 * 20 ms = one second.
    coarse = solve_held_drive(drive, neural_dt_ms=20, hemo_dt_ms=10)
    fine = solve_held_drive(drive, neural_dt_ms=20, hemo_dt_ms=5)
    assert_array_equal(coarse.times_ms, np.arange(101) * 10)
    assert_array_equal(fine.times_ms[::2], coarse.times_ms)
    assert_allclose(fine.states[::2], coarse.states, rtol=0, atol=2e-12)

    # Exact solution of the decoupled damped oscillator f''+f'/tau_s+(f-1)/feedback_s2=u.
    gamma = 0.5 / 0.65
    omega = np.sqrt(1.0 / 0.41 - gamma**2)
    t = coarse.times_ms / 1000
    expected_s = u * np.exp(-gamma * t) * np.sin(omega * t) / omega
    expected_f = 1 + u * 0.41 * (1 - np.exp(-gamma * t) * (
        np.cos(omega * t) + gamma / omega * np.sin(omega * t)))
    assert_allclose(coarse.states[:, 0], expected_s, rtol=0, atol=2e-13)
    assert_allclose(coarse.states[:, 1], expected_f, rtol=0, atol=2e-13)


def test_held_value_changes_at_the_left_neural_tick():
    traj = solve_held_drive([0.0, 0.5, 0.0], neural_dt_ms=20, hemo_dt_ms=5)
    assert_array_equal(traj.states[:5], np.tile(REST_STATE, (5, 1)))  # up to 20 ms
    assert traj.states[5, 0] > 0  # at 25 ms, inside the second hold
    assert 0 < traj.states[9, 0] < traj.states[8, 0]  # decay after pulse ends at 40 ms


def test_output_clock_averages_bold_after_evolving_and_drops_tail():
    traj = solve_held_drive([0.4] * 53, neural_dt_ms=20, hemo_dt_ms=10)
    assert traj.times_ms[-1] == 1060
    times, releases, means = traj.windowed_bold(period_ms=400)
    assert_array_equal(times, [200, 600])
    assert_array_equal(releases, [400, 800])
    first, second = traj.states[1:41], traj.states[41:81]
    assert_allclose(means, [bold_fraction(first).mean(), bold_fraction(second).mean()],
                    rtol=0, atol=2e-15)
    assert abs(means[0] - bold_fraction(first[-1])) > 1e-6
    assert abs(means[1] - bold_fraction(second.mean(axis=0))) > 1e-8

    times, releases, means = traj.windowed_bold(period_ms=500)
    assert_array_equal(times, [250, 750])
    assert_array_equal(releases, [500, 1000])
    assert means.shape == (2,)
    assert all(x.shape == (0,) for x in traj.windowed_bold(period_ms=1080))


def test_window_rectangular_quadrature_refines_without_changing_physical_time():
    drive = [0.4] * 40
    estimates = []
    for h_ms in [10, 5, 1]:
        traj = solve_held_drive(drive, neural_dt_ms=20, hemo_dt_ms=h_ms)
        times, releases, means = traj.windowed_bold(period_ms=800)
        assert_array_equal(times, [400])
        assert_array_equal(releases, [800])
        estimates.append(means[0])
    coarse, fine, finer = estimates
    assert abs(fine - finer) < 0.6 * abs(coarse - finer)


def test_non_default_parameters_long_step_approaches_analytical_steady_state():
    p = replace(NOMINAL_PARAMETERS, signal_decay_s=0.9, flow_feedback_s2=0.5, transit_time_s=1.2,
                grubb_exponent=0.25, resting_extraction=0.33, intravascular_ratio=0.8,
                echo_time_s=0.03, resting_blood_volume=0.025)
    u = 0.3
    traj = solve_held_drive(np.full(2000, u), neural_dt_ms=20, hemo_dt_ms=10, parameters=p)
    f = 1 + 0.5 * u
    v = f**0.25
    q = v * (1 - 0.67**(1 / f)) / 0.33
    assert traj.times_ms[-1] == 40000
    assert np.isfinite(traj.states).all() and (traj.states[:, 1:] > 0).all()
    assert_allclose(traj.states[-1], [0, f, v, q], rtol=0, atol=2e-9)
    expected_readout = 0.025 * (1.715571 * (1 - q) + 0.198 * (1 - q / v) + 0.2 * (1 - v))
    assert_allclose(bold_fraction(traj.states[-1], p), expected_readout, rtol=0, atol=2e-9)


@pytest.mark.parametrize("name,value", [
    ("signal_decay_s", 0), ("transit_time_s", np.nan), ("grubb_exponent", 1.1),
    ("resting_extraction", 1), ("resting_blood_volume", 4),
])
def test_invalid_parameter_rejected(name, value):
    with pytest.raises(ValueError, match=name):
        replace(NOMINAL_PARAMETERS, **{name: value})


@pytest.mark.parametrize("neural_dt_ms,hemo_dt_ms", [(20, 6), (20, 40), (20, 0), (np.inf, 10)])
def test_incompatible_neural_and_hemodynamic_clocks_rejected(neural_dt_ms, hemo_dt_ms):
    with pytest.raises(ValueError, match="clock"):
        solve_held_drive([0.4], neural_dt_ms=neural_dt_ms, hemo_dt_ms=hemo_dt_ms)


def test_output_clock_must_align_to_neural_ticks_not_just_hemodynamic_ticks():
    traj = solve_held_drive([0.4] * 2, neural_dt_ms=20, hemo_dt_ms=10)
    with pytest.raises(ValueError, match="commensurate clocks"):
        traj.windowed_bold(period_ms=30)


def test_invalid_drive_or_nonpositive_integration_state_not_silently_clipped():
    with pytest.raises(ValueError, match="finite one-dimensional held drive"):
        solve_held_drive([np.nan], neural_dt_ms=20, hemo_dt_ms=10)
    with pytest.raises(ValueError, match="positive f, v, q"):
        solve_held_drive([0], neural_dt_ms=20, hemo_dt_ms=10, initial_state=[0, 1, 0, 1])
    with pytest.raises(ValueError, match="positive f, v, q"):
        solve_held_drive([-100.0] * 30, neural_dt_ms=20, hemo_dt_ms=10)
